WITH AccountStats AS (SELECT account_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values, ROUND((100 * SUM(CASE WHEN merchant = 'Amazon' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_amazon FROM transactions WHERE txn_time < '2025-10-01' GROUP BY account_id) SELECT a.status, a.customer_id, A.merchant_values, A.pct_amazon FROM accounts a INNER JOIN AccountStats A ON a.id = A.account_id WHERE A.pct_amazon > 59;
